import {
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DoCheck,
  ElementRef,
  EventEmitter,
  forwardRef,
  HostBinding,
  inject,
  Injector,
  Input,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroupDirective,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
} from '@angular/forms';
import { provideTranslocoScope, translateSignal, TranslocoModule } from '@jsverse/transloco';
import {
  ErrorState,
  injectDestroy,
  voidFn,
} from '@questrade/allspark-angular-components/core/utils';
import {
  QCountryPickerComponent,
  QCountryPickerCountry,
} from '@questrade/allspark-angular-components/country-picker';
import {
  QDropmenuDensity,
  QDropmenuOriginDirective,
} from '@questrade/allspark-angular-components/dropmenu';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { QInputDirective } from '@questrade/allspark-angular-components/input';
import { MISSING_KEY_HANDLER } from '@questrade/allspark-angular-components/transloco';
import { takeUntil } from 'rxjs';
import { QPhoneNumberCountryIsoCode } from './types/phone-number-country-iso-code.type';
import { QPhoneNumberCountryName } from './types/phone-number-country-name.type';
import { QPhoneNumberCountry } from './types/phone-number-country.type';
import { QPhoneNumberGroup } from './types/phone-number-group.type';

let nextUniqueId = 0;

@Component({
  selector: 'q-phone-number',
  templateUrl: './phone-number.component.html',
  styleUrls: ['./phone-number.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [QInputDirective, TranslocoModule, QDropmenuOriginDirective, QCountryPickerComponent],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QPhoneNumberComponent),
      multi: true,
    },
    { provide: FormFieldControl, useExisting: QPhoneNumberComponent },
    provideTranslocoScope({ scope: 'allspark-phone-number' }),
    MISSING_KEY_HANDLER,
  ],
})
export class QPhoneNumberComponent
  extends ErrorState
  implements OnInit, ControlValueAccessor, FormFieldControl, DoCheck
{
  @Output() readonly countryChange = new EventEmitter<QPhoneNumberCountry>();
  @Output() readonly phoneNumberChange = new EventEmitter<string>();

  @Input() countryIsoCode: QPhoneNumberCountryIsoCode = 'CA';
  @Input() value = '';
  @Input() dropmenuDensity: QDropmenuDensity = 'default';
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input({ transform: booleanAttribute }) readonly = false;
  @Input() visibleCountries: QPhoneNumberCountryName[] = [];
  @Input() groups: QPhoneNumberGroup[] = [];
  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-phone-number';

  @Input() set hasError(value: boolean) {
    this._hasError = value;
    this.errorState = value;
    this.stateChanges.next();
  }
  get hasError(): boolean {
    return this._hasError || this.errorState;
  }

  @ViewChild(QCountryPickerComponent, { static: true })
  protected countryPicker!: QCountryPickerComponent;

  @HostBinding('attr.id') controlId = `q-phone-number-${nextUniqueId++}`;
  @HostBinding('class') protected hostClass = 'q-phone-number';

  onChange: (value: string) => void = voidFn;
  onTouch: () => void = voidFn;
  phoneNumberPlaceholder = translateSignal('phoneNumberPlaceholder');

  protected selectedCountry: QPhoneNumberCountry | null = null;

  private _hasError = false;
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);
  private readonly _injector = inject(Injector);
  private readonly _elementRef = inject(ElementRef);
  private readonly _destroy$ = injectDestroy();

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnInit(): void {
    this._setCountryPickerConfig();
    this._setComponentControl();
    this._subscribeToStateChanges();
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();
    }
  }

  onInputChange(event: Event): void {
    const value = (event.target as HTMLInputElement).value.replace(/\D/g, '') as string;
    (event.target as HTMLInputElement).value = value;

    if (this.value === value) return;

    this.value = value;
    this.onChange(this.value);
    this._updateErrorState();
    this.phoneNumberChange.emit(this.value);
    this._changeDetectorRef.markForCheck();
  }

  onCountryChange(event: QCountryPickerCountry): void {
    this.countryChange.emit(event);
  }

  onBlur(): void {
    this.onTouch();
  }

  /** @hidden */
  writeValue(value: string): void {
    this.value = value;

    this._changeDetectorRef.markForCheck();
  }

  /** @hidden */
  registerOnChange(fn: (_: string) => void): void {
    this.onChange = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this.onTouch = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
    this._changeDetectorRef.markForCheck();
  }

  private _setComponentControl(): void {
    const injectedControl = this._injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }

  private _subscribeToStateChanges(): void {
    this.stateChanges.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._changeDetectorRef.markForCheck();
    });
  }

  private _setCountryPickerConfig(): void {
    this.countryPicker.customHostElement = this._elementRef;
    this.countryPicker.showTriggerCountryName = false;
    this.countryPicker.showTriggerCode = true;
    this.countryPicker.showOptionCode = true;
  }
}
